#include <algorithm>
#include <iostream>
#include <stdexcept>
#include <vector>
int summarize(const std::vector<int>& data, bool highest) {
    if (data.empty() || data.size() > 1000)
        throw std::invalid_argument("size");
    for (int sample : data)
        if (sample < 0 || sample > 1000)
            throw std::invalid_argument("sample");
    if (highest)
        return *std::max_element(data.begin(), data.end());
    int sum = 0;
    for (int sample : data) sum += sample;
    return sum / static_cast<int>(data.size());
}
int main() {
    const std::vector<int> data{2, 4, 9};
    std::cout << "average=" << summarize(data, false) << '\n';
    std::cout << "highest=" << summarize(data, true) << '\n';
}

#include <algorithm>
#include <iostream>
#include <stdexcept>
#include <vector>
int changing_middle(std::vector<int>& data) {
    if (data.empty() || data.size() % 2 == 0)
        throw std::invalid_argument("positive odd size required");
    std::sort(data.begin(), data.end()); // Changes caller storage.
    return data[data.size() / 2];
}
int preserving_middle(const std::vector<int>& data) {
    auto copy = data; // This value owns a separate vector.
    return changing_middle(copy);
}
void show(const std::vector<int>& data) {
    for (int x : data) std::cout << x << ' ';
    std::cout << '\n';
}
int main() {
    std::vector<int> changed{9, 1, 4};
    const std::vector<int> kept{9, 1, 4};
    std::cout << "changing=" << changing_middle(changed) << '\n';
    show(changed);
    std::cout << "preserving=" << preserving_middle(kept) << '\n';
    show(kept);
}

