#include <utility>
template<class E, class F> bool dpx_rejects(F&& action) {
  try { std::forward<F>(action)(); }
  catch (const E&) { return true; }
  return false;
}

int main() {
std::cout << std::boolalpha << ([]{
  Monitor m(std::make_unique<Middle>());
  return dpx_rejects<std::invalid_argument>([&]{
    m.read({
    });
  });
})() << '\n';
}

